import { getConfig } from './config.js'
import { logSuccess } from '../../lib/output/logger.js'

export default async function configSet(key: string, value: string): Promise<void> {
  const config = getConfig()
  const parsed: unknown = value === 'true' ? true : value === 'false' ? false : !isNaN(Number(value)) ? Number(value) : value
  config.set(key, parsed)
  logSuccess(`Config ${key} set to ${value}`)
}
